                "artifact_id": entry.artifact_id,
                "name": entry.name,
                "role": entry.role.value,
                "size": entry.size_bytes,
                "sha256": entry.sha256,
                "media_type": entry.media_type,
            }
        )
    return {"artifacts": artifacts, "degraded": degraded}


