    const tasksAtRequestStart = useAgentStore.getState().tasksById;
    useAgentStore.getState().setHistoryState("loading");
    try {
      const page = excludeDeletedTasks(
        await this.api.fetchTasks({ limit: TASK_PAGE_SIZE }),
        this.deletedTaskIds,
